// Extract and normalize the incoming Supabase event
const body = $input.first().json.body || $input.first().json;

const eventType = body.type || body.event_type || 'UNKNOWN';
const record = body.record || body;
const oldRecord = body.old_record || {};

const agent = (record.agent || '').toLowerCase().trim();
const owner = (record.owner || '').toLowerCase().trim();
const status = record.status || '';
const priority = record.priority || '';
const urgency = record.urgency || '';
const taskId = record.id || '';
const title = record.title || '';
const venture = record.venture || '';

const isHighPriority = (
  priority === 'pri-0' ||
  urgency === 'CRITICAL' ||
  urgency === 'high' ||
  status === 'blocked' ||
  (status === 'done' && oldRecord.status !== 'done')
);

const statusChanged = oldRecord.status && oldRecord.status !== status;
const agentChanged = oldRecord.agent && oldRecord.agent !== agent;

// Loop guard: suppress dispatch when an agent wrote a task assigned to itself with status=waiting.
// These are self-queued tasks for later human review, NOT dispatch triggers.
// Without this guard, agents with Execute Workflow Trigger loop infinitely (Priya bug, 2026-04-20).
// Self-queued task detection (loop prevention).
// Catches BOTH INSERT and UPDATE events since agents using UPSERT produce UPDATE on re-runs.
// Only suppresses when owner == agent AND status is non-actionable (waiting / queued by self).
const isSelfQueuedTask = (
  agent && agent === owner && status === 'waiting' &&
  // Only skip if the task content itself didn't change meaningfully.
  // If status changed from non-waiting to waiting, allow dispatch (state transition).
  (!oldRecord.status || oldRecord.status === 'waiting')
);

// Only dispatch on meaningful events. Skip self-queued INSERTs.
const shouldDispatch = !isSelfQueuedTask;

return [{
  json: {
    eventType,
    agent,
    owner,
    status,
    priority,
    urgency,
    taskId,
    title,
    venture,
    isHighPriority,
    statusChanged,
    agentChanged,
    isSelfQueuedTask,
    shouldDispatch,
    record,
    oldRecord,
    timestamp: new Date().toISOString()
  }
}];

// Agent Router - routes task events to the correct agent handler
const item = $input.first().json;
const agent = item.agent;

const validAgents = ['agatha','marcus','arlo','vera','zara','felix','cleo','nell','maya','nova','leo','priya','hunter','kai'];

const result = {
  agent: agent,
  isKnownAgent: validAgents.includes(agent),
  taskId: item.taskId,
  title: item.title,
  status: item.status,
  priority: item.priority,
  urgency: item.urgency,
  eventType: item.eventType,
  venture: item.venture,
  record: item.record,
  oldRecord: item.oldRecord,
  statusChanged: item.statusChanged,
  agentChanged: item.agentChanged,
  shouldDispatch: item.shouldDispatch !== false,
  timestamp: item.timestamp,
  routedAt: new Date().toISOString()
};

return [{ json: result }];

// Agent Dispatch - routes to correct workflow per agent
const item = $input.first().json;
const agent = item.agent;

// Canonical agent-to-workflow mapping (updated 2026-04-17)
const agentWorkflowMap = {
  'zara': 'xAfMItfI8UfAqb3M',
  'felix': 'gnwpyTFbusBrZG7P',
  'leo': 'pyr9wurcs1M9utW3',
  'nell': '8DlMfyTYsbnQGYR2',
  'kai': 'fBgBwoAg0YdkabtU',
  'cleo': 'AnhkJrJBvmohfqjJ',
  'vera': 'l0nujD2PBYGeEtXx',
  'marcus': 'TI1ozQbPtI69qlgO',
  'nova': 'hCbvRXoGWaqG1Znx',
  'maya': 'JtyxjXRQLPKB37DD',
  'hunter': 'z2XxEJbKcz8YuEFq',
  'priya': 'dm2CccS71EVO8kJY',
  'agatha': 'NgVcpJ7PO7sTYvm9'
};

const targetWorkflow = agentWorkflowMap[agent] || null;

return [{
  json: {
    dispatched: true,
    agent: agent,
    isKnownAgent: item.isKnownAgent,
    targetWorkflow: targetWorkflow,
    hasWorkflow: !!targetWorkflow,
    shouldDispatch: item.shouldDispatch === false ? false : true,
    taskId: item.taskId,
    title: item.title,
    status: item.status,
    eventType: item.eventType,
    message: targetWorkflow 
      ? `Dispatching to workflow ${targetWorkflow} for agent ${agent}`
      : `Event logged for agent ${agent} (no dedicated workflow mapped yet)`,
    timestamp: new Date().toISOString()
  }
}];

// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}

let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'system',
  duration_ms: duration,
  api_calls: $input.first()?.json?.api_call_count || 0,
  cost_usd: $input.first()?.json?.total_cost || 0,
  outcome: $input.first()?.json?.outcome || 'completed',
  outcome_count: $input.first()?.json?.result_count || 0,
  quality_score: $input.first()?.json?.quality_score || null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log' })
};

const response = await __httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
    'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];

// Parse Maya's 4-brief format from the task description.
// Input: $json.record.description (or $json.description as fallback)
// Output: 1 item per brief, each containing Cleo's webhook contract shape.

const VENTURE_TO_CHANNEL = {
  'MINDMAKER': 'house',
  'MINDMAKER-LIVE': 'house',
  'MINDMAKER_LIVE': 'house',
  'PAID': 'paid',
  'BUILT': 'built',
  // Retired brands, kept so a historical brief still routes.
  'TECHONOMIC': 'paid',
  'MYMU': 'house',
  'BUILDER-ECONOMY': 'built',
  'BUILDER_ECONOMY': 'built',
  'ADFIXUS': 'linkedin',
  'SIGNAL-NOISE': 'signal_noise',
  'SIGNAL_NOISE': 'signal_noise',
  'VERTICAL-VIDEO': 'vertical_video',
  'LINKEDIN': 'linkedin'
};

const channelAudience = {
  paid: 'operators, founders and commercial leaders who can act on an economic insight',
  house: 'senior leaders in legacy media and broadcast running AI transformation, plus operators and founders monetizing the open web in the AI era',
  linkedin: 'media and ad-tech professionals in Krish network',
  built: 'solo founders and small teams punching above their headcount with AI',
  signal_noise: 'media and tech executives tracking AI transformation',
  vertical_video: 'builders and operators on IG/TikTok'
};

// Read from Parse Event directly - Agent Dispatch drops record/description
const upstream = $('Parse Event').first().json;
const record = upstream.record || {};
const description = record.description || '';
const taskId = record.id || upstream.taskId || '';

if (!description) {
  return [{ json: {
    brief_num: 0, venture: 'NONE', target_channel: 'linkedin',
    hook: '', target_audience: '', contrarian_angle: '',
    krish_approved: false, parse_error: 'empty description', taskId
  }}];
}

const chunks = description.split(/\n\s*---\s*\n/);
const briefs = [];
for (const chunk of chunks) {
  const headerMatch = chunk.match(/BRIEF\s*(\d+)\s*:\s*([A-Z][A-Z0-9_-]*)/i);
  if (!headerMatch) continue;
  const brief_num = parseInt(headerMatch[1], 10);
  const venture = headerMatch[2].toUpperCase().trim();
  const target_channel = VENTURE_TO_CHANNEL[venture] || 'linkedin';

  const titleMatch = chunk.match(/Title\s*:\s*(.+?)(?:\n|$)/i);
  const keywordMatch = chunk.match(/Keyword\s*:\s*(.+?)(?:\n|$)/i);
  const formatMatch = chunk.match(/Format\s*:\s*(.+?)(?:\n|$)/i);
  const pointsMatch = chunk.match(/Key Points\s*:\s*\n([\s\S]*?)$/i);

  const title = titleMatch ? titleMatch[1].trim() : '';
  const keyword = keywordMatch ? keywordMatch[1].trim() : '';
  const format = formatMatch ? formatMatch[1].trim() : '';
  const points = pointsMatch
    ? pointsMatch[1].split('\n').map(l => l.replace(/^\s*[-*]\s*/, '').trim()).filter(Boolean)
    : [];

  let hook = title;
  let target_audience = channelAudience[target_channel] || 'Krish LinkedIn network';
  let contrarian_angle = points.length > 0 ? ('Most people miss: ' + points.join('; ')) : '';

  briefs.push({
    brief_num, venture, title, keyword, format, points,
    krish_approved: true,
    target_channel, hook, target_audience, contrarian_angle,
    taskId
  });
}

if (briefs.length === 0) {
  return [{ json: {
    brief_num: 0, venture: 'NONE', target_channel: 'linkedin',
    hook: '', target_audience: '', contrarian_angle: '',
    krish_approved: false, parse_error: 'no briefs matched pattern', taskId
  }}];
}

return briefs.map(b => ({ json: b }));
